  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 9, $j$3.1 Spreadsheet Basics$j$, $j${"readings": [{"title": "Proverbs 27 (King James Version)", "url": "/portal/bible/Proverbs/27"}], "body": "A spreadsheet is a program that organizes data in rows and columns and performs calculations. Common programs include Microsoft Excel and Google Sheets. Churches, schools and businesses use spreadsheets for budgets, attendance records, schedules, inventories and grade books. Proverbs 27:23 says, Be thou diligent to know the state of thy flocks, and look well to thy herds. Good records help leaders know the true state of their work.\n\nLearn the parts. A workbook is the whole file, and it holds one or more worksheets, also called sheets or tabs. A worksheet is a grid. A column runs up and down and is labeled with letters. A row runs across and is labeled with numbers. A cell is where a row and a column meet, and each cell has an address called a cell reference, such as B3, which is column B, row 3. A range is a group of cells, written as B2 to B10 with a colon in the program. The active cell is the one you have selected, and the formula bar shows its contents.\n\nCells can hold text, numbers, dates and formulas. Text labels describe the data, such as Name or Amount. Numbers can be formatted as whole numbers, decimals, currency, percentages or dates. Choose the right format so the data is clear. A column of dollar amounts should show currency symbols, and a date should be recognized as a date.\n\nPlan your sheet before you begin. Put a title at the top, use one row for column headings, put each record in its own row and keep each kind of information in its own column. Do not leave random blank rows or columns in a table. Use bold headings, borders, shading and column width to make it readable. Freeze the top row so headings stay visible when you scroll. Name each worksheet clearly.\n\nEnter data carefully, since one wrong number can make every result wrong. Check your work.\n\nYour task: (1) Explain what a cell reference is and give an example. (2) Define workbook, worksheet, row and column. (3) Design a simple table for a class attendance record.\n\nFlorida standards: Florida computer science and digital literacy course standards.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida computer science and digital literacy course standards", "script": "Welcome back. Listen, Proverbs 27:23 says, Be thou diligent to know the state of thy flocks, and look well to thy herds. Good records help leaders know the true state of their work.\n\nNow watch this. A spreadsheet organizes data in rows and columns and performs calculations. Excel and Google Sheets are examples.\n\nA workbook is the whole file. A worksheet is one tab in it. Columns run up and down and have letters. Rows run across and have numbers. A cell is where a row and column meet. Its address is the cell reference, like B3. A range is a group of cells.\n\nCells hold text, numbers, dates and formulas. Format numbers as currency, percentages or dates so the data is clear.\n\nPlan before you begin. Put a title at the top. Use one row for headings. Put each record in its own row. Keep each kind of information in its own column. Freeze the top row. Name your sheets.\n\nEnter data carefully. One wrong number can make every result wrong.\n\nYour task is to explain a cell reference, define the parts of a spreadsheet and design an attendance table. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.1 Spreadsheet Basics$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 10, $j$3.2 Formulas and Functions$j$, $j${"readings": [{"title": "Luke 14 (King James Version)", "url": "/portal/bible/Luke/14"}], "body": "The real power of a spreadsheet is its ability to calculate. A formula is an instruction that tells the spreadsheet to compute a value. Every formula begins with an equals sign. For example, typing equals B2 plus B3 in a cell adds the values in those two cells. The symbols for math are plus for addition, the minus sign for subtraction, an asterisk for multiplication and a slash for division. Spreadsheets follow the order of operations, so parentheses are done first, then multiplication and division, then addition and subtraction.\n\nThe great advantage is that formulas use cell references. If you change a number in B2, every formula using B2 updates automatically. This saves time and reduces errors. Luke 14:28 says, For which of you, intending to build a tower, sitteth not down first, and counteth the cost, whether he have sufficient to finish it? A spreadsheet is a good tool for counting the cost.\n\nA function is a built in formula. The SUM function adds a range. The AVERAGE function finds the mean. MIN finds the smallest value, MAX finds the largest, and COUNT counts the cells that contain numbers. The IF function makes a decision. For example, an IF formula can display Pass when a score is at least 70 and Review when it is lower. Use the formula help in the program to learn others.\n\nCopying a formula changes its references automatically. This is called a relative reference. If you copy a formula down a column, each row uses its own data. Sometimes you need a reference to stay fixed. A dollar sign makes it an absolute reference, as in a tax rate stored in one cell and used in many formulas. A reference like $B$2 does not change when copied.\n\nLearn to read errors. A divide by zero error appears when a formula divides by zero. A reference error appears when a cell used in a formula was deleted. A name error appears when the program does not recognize a function name, often because of a typing mistake. Check your formulas, test them with simple numbers, and compare results to your own estimate.\n\nYour task: (1) Write the formula to add cells B2 through B6 using a function. (2) Explain relative and absolute references. (3) Explain what an IF function does.\n\nFlorida standards: Florida computer science and digital literacy course standards.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida computer science and digital literacy course standards", "script": "Welcome back. Listen, Luke 14:28 says, For which of you, intending to build a tower, sitteth not down first, and counteth the cost? A spreadsheet is a good tool for counting the cost.\n\nNow watch this. A formula is an instruction that calculates a value. Every formula begins with an equals sign. Use plus, minus, an asterisk for multiply and a slash for divide. Parentheses are done first, then multiply and divide, then add and subtract.\n\nFormulas use cell references. Change a number and every formula using it updates automatically.\n\nA function is a built in formula. SUM adds a range. AVERAGE finds the mean. MIN is the smallest. MAX is the largest. COUNT counts cells with numbers. IF makes a decision, like showing Pass when a score is at least 70.\n\nA relative reference changes when you copy a formula. An absolute reference with dollar signs, like $B$2, stays fixed.\n\nLearn the errors. Divide by zero. Reference error when a cell was deleted. Name error when a function is mistyped. Test with simple numbers.\n\nYour task is to write a SUM formula, explain relative and absolute references and explain IF. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.2 Formulas and Functions$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 11, $j$3.3 Charts and Data Visualization$j$, $j${"readings": [{"title": "Proverbs 14 (King James Version)", "url": "/portal/bible/Proverbs/14"}], "body": "Numbers are easier to understand when they are shown in a picture. A chart turns data into a visual that reveals patterns, comparisons and trends. Habakkuk 2:2 says, Write the vision, and make it plain upon tables, that he may run that readeth it. A good chart makes information plain.\n\nChoose the right chart for the job. A column or bar chart compares amounts among categories, such as attendance by service or giving by month. A line chart shows change over time, such as weekly attendance across a year. A pie chart shows parts of a whole, such as a budget, and works best with a small number of slices that add to one hundred percent. A scatter chart shows the relationship between two numbers, such as hours studied and test score. Choose the simplest chart that tells the story.\n\nBuild a chart in steps. Organize your data in a clear table with headings. Select the data. Insert the chart type. Then improve it. Add a clear title that says what the chart shows. Label the axes, including units such as dollars or people. Add a legend when there is more than one data series. Use readable colors with good contrast, and consider people who have trouble telling certain colors apart. Remove clutter such as heavy gridlines and three dimensional effects that make values hard to read.\n\nCharts can mislead, so be honest. Proverbs 14:15 says, The simple believeth every word: but the prudent man looketh well to his going. A bar chart that starts its vertical axis above zero can make a small difference look huge. Leaving out part of the data, using uneven scales or choosing only favorable dates can mislead the reader. Proverbs 11:1 says, A false balance is abomination to the LORD: but a just weight is his delight. Present data truthfully and cite where it came from.\n\nA dashboard combines several charts and key numbers on one page so leaders can see how things stand at a glance.\n\nYour task: (1) Match four chart types to the data they show best. (2) List five parts of a good chart. (3) Give one example of a misleading chart and explain how to fix it.\n\nFlorida standards: Florida computer science and digital literacy course standards.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida computer science and digital literacy course standards", "script": "Welcome back. Listen, Habakkuk 2:2 says, Write the vision, and make it plain upon tables, that he may run that readeth it. A good chart makes information plain.\n\nNow watch this. A chart turns data into a picture that shows patterns and trends.\n\nChoose the right chart. A column or bar chart compares categories. A line chart shows change over time. A pie chart shows parts of a whole, with a few slices that total one hundred percent. A scatter chart shows the relationship between two numbers.\n\nTo build one, organize your data, select it, insert the chart, then improve it. Add a clear title. Label the axes with units. Add a legend when needed. Use readable colors. Remove clutter.\n\nBe honest. Proverbs 14:15 says, The simple believeth every word: but the prudent man looketh well to his going. A bar chart that does not start at zero can make a small difference look huge. Proverbs 11:1 says, a just weight is his delight. Show data truthfully and cite the source.\n\nA dashboard combines charts and key numbers on one page.\n\nYour task is to match charts to data, list the parts of a good chart and fix a misleading chart. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.3 Charts and Data Visualization$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 12, $j$3.4 Data Analysis and Data Ethics$j$, $j${"readings": [{"title": "Proverbs 18 (King James Version)", "url": "/portal/bible/Proverbs/18"}], "body": "Data is facts and figures collected for a purpose. Data analysis is the process of cleaning, organizing and studying data to answer questions and make decisions. Proverbs 18:13 says, He that answereth a matter before he heareth it, it is folly and shame unto him. Wise leaders look at the facts before they decide.\n\nBegin by cleaning the data. Look for typing errors, misspelled names, inconsistent formats such as two ways of writing the same date, blank cells and duplicate records. Dirty data produces wrong answers. Keep an untouched copy of the original data, and do your cleaning on a copy.\n\nLearn core tools. Sorting puts rows in order, such as from the highest amount to the lowest or by last name. Filtering shows only the rows that meet a condition, such as members who attended in March. Conditional formatting colors cells that meet a rule, such as turning a low balance red. A pivot table summarizes large data, for example totalling giving by month or counting students by grade. Formulas such as SUMIF and COUNTIF add or count only items that meet a condition.\n\nAsk good questions and read results carefully. What is the data telling you? What does it not tell you? A pattern does not always show cause. Two things can happen together without one causing the other. Be careful about small samples and about numbers with no context. Check that your conclusions follow from the evidence.\n\nData ethics matters because data often concerns people. Collect only what you need, and protect it. Sensitive information such as financial records, health information, student records and attendance of minors must be kept private and shared only with those who have a right to see it. Get permission when you collect data about others. Protect files with passwords and limited access. Avoid bias by not choosing data that supports only what you hope to find. Report honestly, including results you did not expect. Exodus 20:16 says, Thou shalt not bear false witness against thy neighbour.\n\nYour task: (1) List four steps in cleaning data. (2) Explain the difference between sorting and filtering. (3) Describe two ways to protect private data.\n\nFlorida standards: Florida computer science and digital literacy course standards.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida computer science and digital literacy course standards", "script": "Welcome back. Listen, Proverbs 18:13 says, He that answereth a matter before he heareth it, it is folly and shame unto him. Wise leaders look at the facts before they decide.\n\nNow watch this. Data analysis means cleaning, organizing and studying data to answer questions. Start by cleaning. Look for typing errors, inconsistent formats, blank cells and duplicates. Keep an untouched copy of the original.\n\nSorting puts rows in order. Filtering shows only the rows that meet a condition. Conditional formatting colors cells that meet a rule. A pivot table summarizes large data. SUMIF and COUNTIF add or count only what meets a condition.\n\nAsk good questions. Two things can happen together without one causing the other. Be careful with small samples and numbers with no context.\n\nData ethics matters. Collect only what you need and protect it. Financial records, health information and student records are private. Get permission. Use passwords and limited access. Do not choose data to support only what you hope to find. Exodus 20:16 says, Thou shalt not bear false witness.\n\nYour task is to list steps for cleaning data, compare sorting and filtering and describe two ways to protect private data. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.4 Data Analysis and Data Ethics$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 3, $j$Assessment 3: Spreadsheets and Data$j$, $j${"prompt": "Write a report of at least 250 words, with calculations, on spreadsheets and data. Use complete sentences and label each part. Proverbs 27:23 says, Be thou diligent to know the state of thy flocks, and look well to thy herds.\n\nPart 1: Explain the terms workbook, worksheet, cell, cell reference, row, column and range. Design a table for a church attendance record with at least five column headings.\nPart 2: A set of five weekly attendance numbers is 45, 52, 38, 60 and 55. Calculate the sum, the average, the minimum and the maximum by hand, and write the spreadsheet function you would use for each.\nPart 3: Explain relative and absolute references, and write an IF formula idea that shows Pass when a score is 70 or higher.\nPart 4: Choose the best chart type for each of these: giving by month, parts of a budget, attendance across a year, and hours studied against test score. Explain how a chart can mislead and how to prevent it.\nPart 5: Describe four steps for cleaning data, explain sorting, filtering and pivot tables, and describe how to protect private data. Apply Proverbs 18:13 and Exodus 20:16.", "rubric": "100 points. Part 1: 20 points. Part 2: 25 points. Part 3: 15 points. Part 4: 20 points. Part 5: 15 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 3: Spreadsheets and Data$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 3, $j$Discussion 3: Look Well to Thy Herds$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a record or list that a church, team or family might keep in a spreadsheet, with no private details, (2) explains in your own words why accurate records matter, (3) explains why honest charts and careful handling of private data are matters of integrity, and (4) connects your answer to Proverbs 27:23, Proverbs 11:1, Proverbs 18:13 or Exodus 20:16. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Who should be allowed to see the attendance and giving records of a church? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 3: Look Well to Thy Herds$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 11, $j$Check 3.1: Spreadsheet Basics$j$, $j${"questions": [{"q": "The address of the cell in column C, row 5 is:", "options": ["5C row", "CC5", "C5", "R5C"]}, {"q": "A whole spreadsheet file is called a:", "options": ["Workbook", "Cell", "Range", "Formula"]}, {"q": "Columns in a spreadsheet are labeled with:", "options": ["Numbers only", "Colors", "Symbols", "Letters"]}, {"q": "Freezing the top row helps by:", "options": ["Deleting data", "Locking the file forever", "Keeping headings visible while scrolling", "Adding formulas"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Spreadsheet Basics$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,3,2}'::int[], array[$j$Cell references use the column letter then the row number.$j$,$j$A workbook holds one or more worksheets.$j$,$j$Columns use letters; rows use numbers.$j$,$j$Headings stay in view.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Spreadsheet Basics$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 12, $j$Check 3.2: Formulas and Functions$j$, $j${"questions": [{"q": "Every spreadsheet formula begins with:", "options": ["A dollar sign", "A period", "An equals sign", "A quotation mark"]}, {"q": "Which function adds a range of numbers?", "options": ["COUNT", "MIN", "IF", "SUM"]}, {"q": "A reference that does not change when copied is:", "options": ["Absolute", "Hidden", "Relative", "Broken"]}, {"q": "The AVERAGE of 10, 20 and 30 is:", "options": ["30", "60", "10", "20"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Formulas and Functions$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,0,3}'::int[], array[$j$Formulas start with equals.$j$,$j$SUM totals values.$j$,$j$Dollar signs make references absolute.$j$,$j$60 divided by 3 equals 20.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Formulas and Functions$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 13, $j$Check 3.3: Charts and Data Visualization$j$, $j${"questions": [{"q": "Which chart best shows change over time?", "options": ["Pie chart", "Line chart", "Table of contents", "Photograph"]}, {"q": "A pie chart is best for showing:", "options": ["A password", "Two unrelated lists", "Parts of a whole", "Hourly change"]}, {"q": "A chart title should:", "options": ["Say what the chart shows", "Hide the data", "Use only symbols", "Be left blank"]}, {"q": "A vertical axis that starts far above zero on a bar chart can:", "options": ["Make data more accurate", "Print faster", "Exaggerate small differences", "Remove errors"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Charts and Data Visualization$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,0,2}'::int[], array[$j$Line charts show trends over time.$j$,$j$Pie slices represent shares of a total.$j$,$j$Titles explain the chart.$j$,$j$Truncated axes can mislead.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Charts and Data Visualization$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 14, $j$Check 3.4: Data Analysis and Data Ethics$j$, $j${"questions": [{"q": "Showing only the rows that meet a condition is called:", "options": ["Backing up", "Sorting", "Filtering", "Freezing"]}, {"q": "Duplicate records and typing errors are examples of:", "options": ["Dirty data", "Charts", "Clean data", "Passwords"]}, {"q": "A pivot table is used to:", "options": ["Send email", "Change the font", "Delete files", "Summarize large data"]}, {"q": "Student records and financial records should be:", "options": ["Posted online", "Shared with everyone", "Kept private and protected", "Left unlocked"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Data Analysis and Data Ethics$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,3,2}'::int[], array[$j$A filter hides rows that do not match.$j$,$j$They must be fixed before analysis.$j$,$j$Pivot tables summarize and group data.$j$,$j$Sensitive data needs protection.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Data Analysis and Data Ethics$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 15, $j$Unit Quiz 3: Spreadsheets and Data$j$, $j${"questions": [{"q": "A spreadsheet cell reference is made up of:", "options": ["Two letters", "A file extension", "A column letter and a row number", "A password"]}, {"q": "The formula that adds cells B2 to B6 uses the function:", "options": ["SUM", "COUNT", "MIN", "PRINT"]}, {"q": "The AVERAGE of 40, 50 and 60 is:", "options": ["40", "60", "150", "50"]}, {"q": "The symbols $B$2 show a:", "options": ["Absolute reference", "Relative reference", "Chart", "Filter"]}, {"q": "The best chart for parts of a budget is a:", "options": ["Bar code", "Pie chart", "Scatter chart only", "Line chart"]}, {"q": "A chart axis that starts well above zero on a bar chart may:", "options": ["Fix the data", "Improve honesty", "Protect privacy", "Mislead the reader"]}, {"q": "Before analyzing data, it is wise to:", "options": ["Publish it", "Clean it and keep a copy of the original", "Delete the original", "Ignore errors"]}, {"q": "Exodus 20:16 forbids:", "options": ["Working hard", "Saving data", "Bearing false witness", "Using charts"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Spreadsheets and Data$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,3,0,1,3,1,2}'::int[], array[$j$For example, D7.$j$,$j$SUM adds a range.$j$,$j$150 divided by 3 equals 50.$j$,$j$Dollar signs fix the reference.$j$,$j$A pie shows shares of a whole.$j$,$j$Truncated axes exaggerate differences.$j$,$j$Clean on a copy.$j$,$j$Data must be reported truthfully.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Spreadsheets and Data$j$ on conflict (item_id) do nothing;
